// Isolation test (OS-12) — construct Chains with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import type { Currency, Unit } from "../src/catalog/index.js";
import { LineageReader } from "../src/facts/index.js";
import { Chains } from "../src/condition/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";
import { factWorld, never } from "./support/fact-world.js";

const [u, v] = ["u1", "u2"] as unknown as readonly [Unit, Unit];
const c0 = "c0" as Currency;

/** u independent at c0; v inherits from u's commitment and commits to it. */
function world() {
  const w = factWorld({ currencies: ["c0", "c1"], invalidations: never });
  const ku = w.commitAt(u, c0);
  w.declarations.declare(v, "easy", "HUMAN");
  const h0 = w.record.noise();
  const context = w.draws.recordDraw(v, {}, h0, "inherit", h0, "ENGINE");
  if ("kind" in context) throw new Error("setup: the draw was refused");
  const k = w.candidates.appendCandidate({ context, unit: v, currency: c0, condition: "inherit", seed: "s", from: ku }, "sig", w.record.noise(), "ENGINE");
  if ("kind" in k) throw new Error("setup: the candidate was refused");
  w.commitments.commit(k, "HUMAN");
  const parts = { lineage: new LineageReader({ record: w.record }), commitments: w.commitments, currencies: w.order };
  return { ...w, parts };
}

describe("Chains in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { parts } = world();
    for (const missing of Object.keys(parts)) expect(() => new Chains({ ...parts, [missing]: undefined } as never), missing).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { parts } = world();
    for (const slot of Object.keys(parts)) expect(() => new Chains({ ...parts, [slot]: {} } as never), slot).toThrow();
  });

  it("chains answers differently when lineage, commitments or currencies differ", () => {
    const w = world();
    const h = w.record.noise();
    const real = new Chains(w.parts).chains().compute(h);
    expect(real.map((c) => c.units)).toEqual([[u, v]]);
    expect(new Chains({ ...w.parts, lineage: new LineageReader({ record: inMemoryRecord() }) }).chains().compute(h)).not.toEqual(real);
    expect(new Chains({ ...w.parts, commitments: { effectiveCommitment: () => ({ kind: "no-subject" }) } }).chains().compute(h)).not.toEqual(real);
    expect(new Chains({ ...w.parts, currencies: { predecessors: () => [c0] } }).chains().compute(h)).not.toEqual(real);
  });
});
